from datetime import date


class Library:
    def __init__(self, loan_days: int = 14, daily_fine: float = 0.5) -> None:
        self.loan_days = loan_days
        self.daily_fine = daily_fine
        # book_id -> user who currently holds it (or absent if available)
        self._loans = {}
        # user -> {book_id: borrow_day} for books currently held
        self._held = {}
        # user -> accumulated unpaid fines
        self._fines = {}
        # set of known books
        self._books = set()

    def add_book(self, book_id: str) -> None:
        self._books.add(book_id)

    def borrow(self, user: str, book_id: str, day: date) -> None:
        if book_id not in self._books:
            raise ValueError(f"Unknown book: {book_id}")
        if book_id in self._loans:
            raise ValueError(f"Book {book_id} is currently borrowed")
        # Rule 1: a user with unpaid fines may hold at most one book
        if self._fines.get(user, 0.0) > 0:
            if self._held.get(user):
                raise ValueError(
                    f"User {user} has unpaid fines and already holds a book"
                )
        self._loans[book_id] = user
        self._held.setdefault(user, {})[book_id] = day

    def return_book(self, user: str, book_id: str, day: date) -> float:
        held = self._held.get(user)
        if not held or book_id not in held:
            raise ValueError(
                f"User {user} has not borrowed book {book_id}"
            )
        borrow_day = held.pop(book_id)
        if not held:
            del self._held[user]
        if self._loans.get(book_id) == user:
            del self._loans[book_id]

        due = borrow_day.toordinal() + self.loan_days
        late_days = day.toordinal() - due
        fine = 0.0
        if late_days > 0:
            fine = late_days * self.daily_fine
            self._fines[user] = self._fines.get(user, 0.0) + fine
        return fine

    def unpaid_fines(self, user: str) -> float:
        return self._fines.get(user, 0.0)

    def pay(self, user: str) -> None:
        if user in self._fines:
            self._fines[user] = 0.0
